--
-- Table structure for table `import_history`
--

DROP TABLE IF EXISTS `import_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `import_history` (
  `id` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_id` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上传的文件名',
  `broker_template` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '券商模板类型',
  `import_source` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'csv_import' COMMENT '导入来源标识',
  `total_rows` int NOT NULL COMMENT 'CSV总行数',
  `success_count` int DEFAULT '0' COMMENT '成功导入条数',
  `failed_count` int DEFAULT '0' COMMENT '失败条数',
  `duplicate_count` int DEFAULT '0' COMMENT '重复跳过条数',
  `error_details` json DEFAULT NULL COMMENT '错误详情JSON: [{row: 1, error: ''msg''}]',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '导入开始时间',
  `completed_at` datetime DEFAULT NULL COMMENT '导入完成时间',
  PRIMARY KEY (`id`),
  KEY `account_id` (`account_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `import_history_ibfk_1` FOREIGN KEY (`account_id`) REFERENCES `trade_accounts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `import_history_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

